import { Document } from '../document';
import { formatLongDate } from '../format';
import type { CredentialState, CredentialView } from './credential';

export interface CertificatePageProps {
  /** This page's URL. */
  url: string;
  /** The credential's page (and id). */
  credentialUrl: string;
  stylesheet: string;
  credential: CredentialView;
  /** A QR code (SVG markup generated by the server) linking to the credential page. */
  qrSvg: string;
}

const STATE_NOTE: Partial<Record<CredentialState, string>> = {
  revoked: 'Revoked by the issuer',
  expired: 'Expired',
  not_yet_valid: 'Not valid yet',
};

/**
 * A printable certificate (design plan §3, item 1): a print layout of the same signed credential,
 * not a separate document. The browser's Print command saves it as a PDF.
 */
export function CertificatePage({
  url,
  credentialUrl,
  stylesheet,
  credential: c,
  qrSvg,
}: CertificatePageProps) {
  const note = STATE_NOTE[c.state];
  return (
    <Document
      title={`Certificate: ${c.achievement.name}${c.recipientName ? ` · ${c.recipientName}` : ''}`}
      description={`${c.issuer.name} awarded ${c.recipientName ?? 'this badge'} ${c.achievement.name}.`}
      url={url}
      stylesheet={stylesheet}
      noindex
      bodyClassName="min-h-screen bg-ink/5 font-sans text-ink antialiased print:bg-white"
    >
      <main className="mx-auto max-w-5xl px-4 py-8 print:max-w-none print:p-0">
        <p className="mb-4 flex flex-wrap justify-between gap-2 text-sm text-ink-muted print:hidden">
          <span>
            To save it as a PDF, use your browser’s Print command and choose “Save as PDF”.
          </span>
          <a
            href={credentialUrl}
            className="font-semibold text-signal-strong underline underline-offset-4"
          >
            Back to the badge
          </a>
        </p>
        <article className="certificate relative overflow-hidden rounded-sm border-[6px] border-double border-ink bg-white px-6 py-10 sm:px-14 sm:py-14 print:rounded-none">
          <div aria-hidden="true" className="absolute top-0 left-0 h-2 w-2/5 bg-signal" />
          <div aria-hidden="true" className="absolute right-0 bottom-0 h-2 w-1/4 bg-spark" />
          <header className="flex items-center gap-4">
            {c.issuer.logoUrl && (
              <img
                src={c.issuer.logoUrl}
                alt=""
                width={56}
                height={56}
                className="size-14 object-contain"
              />
            )}
            <p className="text-lg font-bold">{c.issuer.name}</p>
          </header>

          {note && (
            <p className="mt-6 inline-block rounded border-2 border-danger px-3 py-1 font-bold tracking-wide text-danger uppercase">
              {note}
            </p>
          )}

          <div className="mt-10 grid items-center gap-10 sm:grid-cols-[1fr_11rem]">
            <div>
              <p className="text-sm font-bold tracking-[0.2em] text-signal-strong uppercase">
                {c.achievement.typeLabel}
              </p>
              <h1 className="mt-2 text-3xl font-bold tracking-tight text-balance sm:text-5xl">
                {c.achievement.name}
              </h1>
              {c.recipientName && (
                <>
                  <p className="mt-8 text-ink-muted">Awarded to</p>
                  <p className="mt-1 text-3xl font-semibold sm:text-4xl">{c.recipientName}</p>
                </>
              )}
              <p className="mt-6 max-w-2xl leading-relaxed text-ink-muted">
                {c.achievement.description}
              </p>
            </div>
            {c.image && (
              <img
                src={c.image.url}
                alt={c.image.alt}
                width={176}
                height={176}
                className="mx-auto size-44 object-contain"
              />
            )}
          </div>

          <footer className="mt-12 flex flex-wrap items-end justify-between gap-8 border-t border-ink/15 pt-6 text-sm">
            <dl className="grid gap-3 sm:grid-cols-2 sm:gap-x-12">
              <div>
                <dt className="text-ink-muted">Awarded</dt>
                <dd className="font-semibold">
                  <time dateTime={c.validFrom.toISOString()}>{formatLongDate(c.validFrom)}</time>
                </dd>
              </div>
              {c.validUntil && (
                <div>
                  <dt className="text-ink-muted">
                    {c.state === 'expired' ? 'Expired' : 'Expires'}
                  </dt>
                  <dd className="font-semibold">
                    <time dateTime={c.validUntil.toISOString()}>
                      {formatLongDate(c.validUntil)}
                    </time>
                  </dd>
                </div>
              )}
              <div className="sm:col-span-2">
                <dt className="text-ink-muted">Check it at</dt>
                <dd className="font-mono text-xs break-all">{credentialUrl}</dd>
              </div>
            </dl>
            <div
              role="img"
              aria-label="QR code that opens the badge page"
              className="size-28 shrink-0 [&>svg]:size-full"
              // Generated by the server from the credential URL (the qrcode package), not user input.
              // biome-ignore lint/security/noDangerouslySetInnerHtml: server-generated SVG
              dangerouslySetInnerHTML={{ __html: qrSvg }}
            />
          </footer>
        </article>
        <p className="mt-4 text-xs text-ink-muted print:mt-2">
          An Open Badges 3.0 credential, signed by {c.issuer.name}. Hosted on credforge.
        </p>
      </main>
    </Document>
  );
}
